=== author.query.ts
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT a.id, a.name,
    (SELECT count(*)::int FROM book b WHERE b.author_id = a.id AND b.published) AS "publishedBooks",
    (SELECT coalesce(json_agg(json_build_object('id', b.id, 'title', b.title) ORDER BY b.id), '[]')
       FROM book b WHERE b.author_id = a.id AND b.published) AS books
    FROM author a`;
}

=== book.command.ts
export function update(input, ctx) {
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("priceCents" in input) ctx.db.exec(ctx.sql`UPDATE book SET price_cents = ${input.priceCents} WHERE id = ${ctx.id}`);
  if ("stock" in input) ctx.db.exec(ctx.sql`UPDATE book SET stock = ${input.stock} WHERE id = ${ctx.id}`);
}

=== book.query.ts
export default function query(ctx: QueryContext): Sql {
  // Unpublished books are hidden from reads, but PATCH looks them up.
  const visible = ctx.phase === "lookup" ? ctx.sql`TRUE` : ctx.sql`b.published`;
  return ctx.sql`SELECT b.id, b.title, b.price_cents AS "priceCents", b.published_at AS "publishedAt",
    b.stock, a.id AS author_id, a.name AS author_name
    FROM book b LEFT JOIN author a ON a.id = b.author_id
    WHERE ${visible}`;
}

=== customer.handler.ts
export default function customer(id: number, ctx) {
  const [row] = ctx.db.query(ctx.sql`SELECT id FROM customer WHERE id = ${id}`);
  if (!row) ctx.reject({ message: `unknown customer ${id}` });
  ctx.set("customer", row.id);
  return null;
}

=== in_stock.handler.ts
export default function inStock(value: boolean, ctx) {
  const stock = ctx.property("stock");
  return value ? ctx.sql`${stock} > 0` : ctx.sql`${stock} = 0`;
}

=== purchase.command.ts
export function create(input, ctx) {
  const customer = ctx.get("customer");
  const ids = input.lines.map((l) => l.bookId).filter((id, i, all) => all.indexOf(id) === i);
  const books = ctx.db.query(ctx.sql`SELECT id, price_cents, stock, published FROM book
    WHERE id = ANY(${ids}) ORDER BY id FOR UPDATE`);
  const byId = {};
  for (const b of books) byId[String(b.id)] = b;

  const wanted = {};
  for (let i = 0; i < input.lines.length; i++) {
    const line = input.lines[i];
    const book = byId[String(line.bookId)];
    if (!book || !book.published) {
      ctx.reject({ message: `book ${line.bookId} is not available`, pointer: `/lines/${i}/bookId`,
        hint: "Only published books can be bought." });
    }
    wanted[String(line.bookId)] = (wanted[String(line.bookId)] || 0) + line.quantity;
  }
  for (const id of Object.keys(wanted)) {
    if (byId[id].stock < wanted[id]) {
      ctx.reject({ message: `not enough stock for book ${id}`, status: 409, code: "insufficient_stock" });
    }
  }

  let total = 0;
  for (const line of input.lines) total += byId[String(line.bookId)].price_cents * line.quantity;

  const res = ctx.fetch("http://127.0.0.1:18090/payments", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: { customerId: customer, amountCents: total },
  });
  let answer = null;
  if (res.ok) {
    try { answer = res.json(); } catch (e) { answer = null; }
  }
  const status = answer ? answer.status : null;
  if (status === "declined") ctx.reject({ message: "payment declined", status: 402, code: "payment_declined" });
  if (status !== "accepted") ctx.reject({ message: "payment service failed", status: 502, code: "payment_failed" });

  const [purchase] = ctx.db.query(ctx.sql`INSERT INTO purchase (customer_id, created_at, total_cents)
    VALUES (${customer}, now(), ${total}) RETURNING id`);
  for (const line of input.lines) {
    ctx.db.exec(ctx.sql`INSERT INTO purchase_line (purchase_id, book_id, quantity, unit_price_cents)
      VALUES (${purchase.id}, ${line.bookId}, ${line.quantity}, ${byId[String(line.bookId)].price_cents})`);
  }
  for (const id of Object.keys(wanted)) {
    ctx.db.exec(ctx.sql`UPDATE book SET stock = stock - ${wanted[id]} WHERE id = ${Number(id)}`);
  }
  return purchase.id;
}

=== purchase.query.ts
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT p.id, p.created_at AS "createdAt", p.total_cents AS "totalCents",
    (SELECT coalesce(json_agg(json_build_object('bookId', l.book_id, 'title', b.title,
        'quantity', l.quantity, 'unitPriceCents', l.unit_price_cents) ORDER BY l.id), '[]')
       FROM purchase_line l JOIN book b ON b.id = l.book_id WHERE l.purchase_id = p.id) AS lines
    FROM purchase p
    WHERE p.customer_id = ${ctx.get("customer")}`;
}

=== sales_report.query.ts
export default function query(ctx: QueryContext): Sql {
  const from = ctx.get("from");
  const to = ctx.get("to");
  if (from && to && from > to) {
    ctx.reject({ message: "from must not be after to", status: 400, code: "invalid_parameter", pointer: "/from" });
  }
  return ctx.sql`SELECT b.title, SUM(l.quantity) AS quantity, SUM(l.quantity * l.unit_price_cents) AS "revenueCents"
    FROM purchase_line l
    JOIN purchase p ON p.id = l.purchase_id
    JOIN book b ON b.id = l.book_id
    WHERE p.created_at >= (${from}::date::timestamp AT TIME ZONE 'UTC')
      AND p.created_at < ((${to}::date + 1)::timestamp AT TIME ZONE 'UTC')
    GROUP BY b.id, b.title
    ORDER BY "revenueCents" DESC, b.title ASC, b.id ASC`;
}

